+// Standalone probe: verify mma.m16n8k16 + ldmatrix fragment layouts.
+// A: 16x16 bf16. B: 16x8 bf16. D = A*B (16x8 f32).
+// smem layout: block-major, each 8x8 bf16 block = 8 rows x 16 bytes contiguous.
+#include <cuda_runtime.h>
+#include <cuda_bf16.h>
+#include <stdio.h>
+#include <stdint.h>
+
+__device__ __forceinline__ void ldmatrix_x4(uint32_t r[4], const void* p) {
+    uint32_t a = (uint32_t)__cvta_generic_to_shared(p);
+    asm volatile("ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];\n"
+                 : "=r"(r[0]), "=r"(r[1]), "=r"(r[2]), "=r"(r[3]) : "r"(a));
+}
+
+// block-major smem: block b at &s[b][0][0], 8 rows x 8 bf16
+__global__ void probe(const __nv_bfloat16* gA, const __nv_bfloat16* gB, float* gD) {
+    __shared__ __nv_bfloat16 sA[4][8][8];
+    __shared__ __nv_bfloat16 sB[2][8][8];
+    int t = threadIdx.x;
+    // A blocks: 0=(r0-7,c0-7) 1=(r0-7,c8-15) 2=(r8-15,c0-7) 3=(r8-15,c8-15)
+    for (int i = t; i < 256; i += 32) {
+        int b = i / 64, rem = i % 64, r = rem / 8, c = rem % 8;
+        int gr = (b & 2) ? r + 8 : r;
+        int gc = (b & 1) ? c + 8 : c;
+        sA[b][r][c] = gA[gr*16 + gc];
+    }
+    for (int i = t; i < 128; i += 32) {
+        int b = i / 64, rem = i % 64, r = rem / 8, c = rem % 8;
+        sB[b][r][c] = gB[(b*8 + r)*8 + c];
+    }
+    __syncthreads();
+
+    int lane = t % 32;
+    uint32_t a[4], b[4];
+    // lane l supplies address of row (l%8) of matrix (l/8); matrices at 128B stride
+    ldmatrix_x4(a, &sA[lane/8][lane%8][0]);
+    ldmatrix_x4(b, &sB[lane/8][lane%8][0]);
+
+    float d[4] = {0.f, 0.f, 0.f, 0.f};
+    asm volatile(
