// Probe 2: determine exactly what ldmatrix.x4 produces from block-major smem,
// and validate mma.m16n8k16 fragment formulas from PTX docs.
// A: 16x16, A[i][j] = i*16+j+1 (unique, bf16-exact). B: 16x8, B[i][j]=1000+i*8+j.
// smem block-major: block b covers rows (b>>1)*8.., cols (b&1)*8..
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <stdio.h>
#include <stdint.h>

__device__ __forceinline__ void ldmatrix_x4(uint32_t r[4], const void* p) {
    uint32_t a = (uint32_t)__cvta_generic_to_shared(p);
    asm volatile("ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];\n"
                 : "=r"(r[0]), "=r"(r[1]), "=r"(r[2]), "=r"(r[3]) : "r"(a));
}

__global__ void probe(const __nv_bfloat16* gA, const __nv_bfloat16* gB,
                      int* oA, int* oB) {
    __shared__ __nv_bfloat16 sA[4][8][8];
    __shared__ __nv_bfloat16 sB[2][8][8];
    int t = threadIdx.x;
    for (int i = t; i < 256; i += 32) {
        int b = i / 64, rem = i % 64, r = rem / 8, c = rem % 8;
        int gr = (b & 2) ? r + 8 : r;
        int gc = (b & 1) ? c + 8 : c;
        sA[b][r][c] = gA[gr*16 + gc];
    }
    for (int i = t; i < 128; i += 32) {
        int b = i / 64, rem = i % 64, r = rem / 8, c = rem % 8;
        sB[b][r][c] = gB[(b*8 + r)*8 + c];
    }
    __syncthreads();
    int lane = t % 32;
    uint32_t a[4], b[4];
    ldmatrix_x4(a, &sA[lane/8][lane%8][0]);
    ldmatrix_x4(b, &sB[lane/8][lane%8][0]);
    // decode as bf16 values: v[2*i] = low half, v[2*i+1] = high half
    uint16_t av[8], bv[4];
    for (int i = 0; i < 4; i++) { av[2*i] = a[i] & 0xffff; av[2*i+1] = a[i] >> 16; }
    for (int i = 0; i < 2; i++) { bv[2*i] = b[i] & 0xffff; bv[2*i+1] = b[i] >> 16; }
